#include <fstream>
#include <iostream>
#include <string>
int main() {
  std::ifstream status("/proc/self/status");
  for (std::string line; std::getline(status, line);) {
    if (line.rfind("TracerPid:", 0) == 0) std::cout << line << "\n";
  }
  std::cout << "minimal control body completed" << std::endl;
  return 0;
}
